import{z as o,x as i,o as t,c as d,q as r,j as l,D as e,d as a,s as n,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"新任务的评测设计","description":"","frontmatter":{"title":"新任务的评测设计","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-newtask-design.md","filePath":"llm/ef-newtask-design.md","lastUpdated":1791413859000}'),m={name:"llm/ef-newtask-design.md"};function h(p,E,C,c,F,g){const A=i("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="新任务的评测设计" tabindex="-1">新任务的评测设计 <a class="header-anchor" href="#新任务的评测设计" aria-label="Permalink to &quot;新任务的评测设计&quot;">​</a></h1><div class="epigraph"><p>一张新卷子不是「找些题」，而是把一句声明逐级翻译成可判定谓词、抽样框、标注规范与冻结版本；翻译走样一步，分数就测别的东西。</p><footer>—— 据 Zhou 等 IFEval 2023、Cronbach 与 Meehl 1955、HELM 扰动设计口径整理</footer></div><p><a href="/llm/ef-capability-taxonomy">上一课</a>的覆盖矩阵标出了空格。本课写怎么把一个空格变成一张能发布、能进回归的卷子。已有零件：<a href="/llm/human-eval-protocol">人评协议</a>管标注规范与信度，<a href="/llm/eval-contamination">去污染</a>管泄漏，<a href="/llm/synthetic-eval-sets">合成评测集</a>管造题，<a href="/llm/eval-variance-seed">统计功效</a>管噪声来源。本课补的是把它们串成一条<strong>从声明到仪器</strong>的设计流水线，并用试点数据决定卷子的生死。后课的功效分析与组合分层默认卷子已经按本课协议冻结。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新任务评测最常见的死法有三种。一是<strong>构念走样</strong>：想测「多步规划」，题面却靠长阅读理解设难度，分数测的是找信息。<span class="marginnote">「构念走样」就是想考 A 却考成了 B：想测多步规划，题面却先给一篇三千字的材料再问规划，读得慢的模型死在阅读上——分数实际量的是阅读而非规划。好比想量身高却让被测者先爬十层楼梯，量出来的数里混进了体力这个无关变量。</span>二是<strong>判定失效</strong>：开放输出配了字符串精确匹配，正确答案因标点或同义被记错——错在仪器不在模型。三是<strong>难度失控</strong>：题全员满分或全员零分，这样的题不携带区分信息，卷子再大也测不出模型间差异。三者共同点是设计时没把「测什么、怎么判、判得动吗」钉成协议，事后无法审计。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线六步，每步留档。<strong>一、声明翻译</strong>：把「更好地完成 X」写成可判定谓词——IFEval 的做法是指令类型可程序验证（它用约二十几种可验证指令把「服从」变成判定题），不可验证的部分划给 rubric 或人评。<strong>二、抽样框</strong>：题从哪个总体抽、覆盖哪些子域与难度层、许可与隐私边界在哪；抽样框写死，补题才算同一张卷。<strong>三、判定器</strong>：能程序的先程序（单测、schema 校验、正则），判不了的标定法官，两段比分栏。<strong>四、标注规范</strong>：判分标准写成人可执行的操作，双人标注仲裁，报一致率。<strong>五、试点</strong>：小样先跑——难度分布、区分度（题分与总分的点二列相关）、判定器一致率；<span class="marginnote">点二列相关不用怕名字：它就是「这道题的得分」与「这张卷的总分」之间的相关，取值在 -1 到 1 之间。经验上低于 0.2 的题分不开强弱；出现负值更要警惕——越强的作答者越容易答错，多半是题面有歧义或参考答案有问题，试点阶段就该回炉。</span>不达标的题回炉而不是硬上。<strong>六、冻结与版本</strong>：题面、判定器、协议哈希一起冻结，发布表绑版本号，进回归集后改动要走变更审批。</p>',7)),(t(),l(s,null,{default:e(()=>[n(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%BB%BB%E5%8A%A1%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20P%5B%22%E5%8F%AF%E5%88%A4%E5%AE%9A%E8%B0%93%E8%AF%8D%E4%B8%8E%20rubric%20%E5%88%86%E7%95%8C%22%5D%0A%20%20P%20--%3E%20F%5B%22%E6%8A%BD%E6%A0%B7%E6%A1%86%EF%BC%9A%E5%AD%90%E5%9F%9F%20%C3%97%20%E9%9A%BE%E5%BA%A6%E5%B1%82%22%5D%0A%20%20F%20--%3E%20J%5B%22%E5%88%A4%E5%AE%9A%E5%99%A8%EF%BC%9A%E7%A8%8B%E5%BA%8F%E5%85%88%E8%A1%8C%EF%BC%8C%E6%B3%95%E5%AE%98%E6%A0%87%E5%AE%9A%22%5D%0A%20%20J%20--%3E%20G%5B%22%E6%A0%87%E6%B3%A8%E8%A7%84%E8%8C%83%E4%B8%8E%E5%8F%8C%E4%BA%BA%E4%BB%B2%E8%A3%81%22%5D%0A%20%20G%20--%3E%20PI%7B%22%E8%AF%95%E7%82%B9%EF%BC%9A%E9%9A%BE%E5%BA%A6%20%2F%20%E5%8C%BA%E5%88%86%E5%BA%A6%20%2F%20%E4%B8%80%E8%87%B4%E7%8E%87%22%7D%0A%20%20PI%20--%3E%7C%22%E4%B8%8D%E8%BE%BE%E6%A0%87%22%7C%20F%0A%20%20PI%20--%3E%7C%22%E8%BE%BE%E6%A0%87%22%7C%20FR%5B%22%E5%86%BB%E7%BB%93%E9%A2%98%E9%9D%A2%E4%B8%8E%E5%8D%8F%E8%AE%AE%E5%93%88%E5%B8%8C%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("区分度是卷子命的机制：一道题的信息量取决于「能力不同的作答者在这道题上得分是否分得开」。全员满分的题把所有能力压成一个数，等效于把样本量乘了个零；试点阶段删掉负区分度的题，比事后堆题量便宜得多。构念效度的机制借用 Cronbach 与 Meehl 的口径：你在卷子上的分数要能沿"),B("strong",null,"效度网络"),a("接上其他已知测量——新规划卷的高分应伴随既有规划类任务的高分与无关任务的中性；若新卷分涨、旧行全部不动，先怀疑构念走样，再庆祝进步。判定器也一样：程序判与标定法官在同一批样本上的分歧率要报，分歧集中在哪类输出，就说明那一类还没被协议覆盖。")],-1)),(t(),l(s,null,{default:e(()=>[n(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E6%96%B0%E5%8D%B7%E5%88%86%E6%95%B0%E4%B8%8A%E6%B6%A8%22%5D%20--%3E%20Q%7B%22%E6%B2%BF%E6%95%88%E5%BA%A6%E7%BD%91%E7%BB%9C%E5%AF%B9%E8%A1%A8%22%7D%0A%20%20Q%20--%3E%7C%22%E6%97%A2%E6%9C%89%E8%A7%84%E5%88%92%E7%B1%BB%E4%BB%BB%E5%8A%A1%E5%90%8C%E6%AD%A5%E4%B8%8A%E6%B6%A8%22%7C%20OK%5B%22%E6%9E%84%E5%BF%B5%E4%B8%80%E8%87%B4%3A%20%E5%8F%AF%E8%83%BD%E6%98%AF%E7%9C%9F%E8%BF%9B%E6%AD%A5%22%5D%0A%20%20Q%20--%3E%7C%22%E6%97%A0%E5%85%B3%E4%BB%BB%E5%8A%A1%E4%B9%9F%E4%B8%80%E8%B5%B7%E6%B6%A8%22%7C%20SUS%5B%22%E6%80%80%E7%96%91%E6%B3%84%E6%BC%8F%E6%88%96%E8%AF%84%E5%88%86%E5%B0%BA%E5%BA%A6%E6%BC%82%E7%A7%BB%22%5D%0A%20%20Q%20--%3E%7C%22%E6%97%A7%E8%A1%8C%E5%85%A8%E9%83%A8%E4%B8%8D%E5%8A%A8%22%7C%20BAD%5B%22%E6%9E%84%E5%BF%B5%E8%B5%B0%E6%A0%B7%3A%3Cbr%2F%3E%E6%96%B0%E5%8D%B7%E6%B5%8B%E7%9A%84%E6%98%AF%E5%88%AB%E7%9A%84%E4%B8%9C%E8%A5%BF%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">试点只需一两百题就能救一张卷：难度全集中在两端的卷子，跑再多样本也画不出模型间的剖面——区分度是设计期属性，不是样本量能补的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>新卷子在发布的瞬间开始贬值：题面外流、题解上网，<a href="/llm/eval-contamination">去污染协议</a>要同步生效，私有门禁卷与公开对表卷分开管。抽样框决定外部效度：来自内网的题对外部场景无发言权，反之亦然，报告口径要写清总体。人写难题贵且慢，合成补量时按<a href="/llm/synthetic-eval-sets">合成评测集</a>的口径验证难度与多样性，别让合成器把难度均匀化。最后，协议冻结与「卷子永不迭代」是两件事：迭代走版本，新旧版本分数不做跨版直接比较——这一条与全课程的版本冻结纪律同源。<span class="marginnote">初学者容易以为「发布后随手改几道题没关系」。哪怕只改一道题，前后分数就不再可比——如同考试中途换了试卷。所以冻结之后任何改动都要发新版本号、走变更审批；旧版本分数只能存档，不能与新版本混在一张表里比大小。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>新任务评测是把声明逐级翻译成谓词、抽样框、判定器、规范、版本，六步留档。</li><li>程序判定先行，法官只接判不了的部分；两段分歧率要报。</li><li>试点看三样：难度分布、区分度、判定一致率；不达标回炉。</li><li>构念效度靠效度网络对表，单一卷子的涨分不自动等于能力涨。</li><li>出处：Zhou 等 IFEval 2023；Cronbach 与 Meehl 1955（构念效度）；HELM 扰动设计口径，按本课程整理。</li></ul>',5))])}const u=o(m,[["render",h]]);export{D as __pageData,u as default};
